// The Home page's "Featured Navitars" strip shows the first three.
export const featuredNavitars: NavitarDesignProps[] = sampleNavitars.slice(0, 3);

// An owned collection card (OWNER MODE only): the design as the
// owner's own — portrait where one exists (else the labelled
// placeholder), tier + signature ability from the collection file
// (never fabricated stats), lore composed from the design's ability
// and flavor text, and the view-only 3D toggle where a web model
// exists (CARD_MODELS). No lock styling of any kind.
const OwnerCard: React.FC<{ design: CollectionDesign }> = ({ design }) => {
  const lore =
    [
      design.abilityName && design.abilityText
        ? `${design.abilityName} — ${design.abilityText}`
        : null,
      design.flavor,
    ]
      .filter(Boolean)
      .join(' ') || undefined;
  return (
    <Grid item xs={12} sm={6} md={4}>
      <NavitarDesign
        name={design.name}
        type={design.element as NavitarDesignProps['type']}
        imageUrl={
          design.portrait ? `${process.env.PUBLIC_URL}/navitars/${design.portrait}` : undefined
        }
        lore={lore}
        tier={design.tier ?? undefined}
        abilityName={design.abilityName ?? undefined}
        placeholderArt={!design.portrait}
        {...CARD_MODELS[design.name]}
      />
    </Grid>
  );
};

