import React from 'react';
import { Box, Button, ButtonGroup, Typography, Grid, Paper, Chip } from '@mui/material';
import { styled } from '@mui/material/styles';
import { NavitarArtImg } from './NavitarArtImg';
import { ModelViewer } from './ModelViewer';
import { elementEmoji } from '../utils/navitarArt';

export interface NavitarDesignProps {
  type:
    'ice' | 'fire' | 'nature' | 'shadow' | 'light' | 'quantum' | 'electric' | 'spiritual' | 'water';
  name: string;
  // Optional for the same reason rarity/stats are: a locked design
  // (see utils/lockedRoster.ts) has no roster level yet, so the Lv.
  // chip hides rather than inventing one.
  level?: number;
  // Optional: a navitar without roster data omits them, and the chip
  // and stat bars are hidden when absent — nothing is invented. (The
  // two bar-loop fighters, Griffin and Ashwing, carry display-default
  // stats so their cards match the roster's — see NavitarShowcase.)
  rarity?: 'common' | 'rare' | 'epic' | 'legendary';
  stats?: {
    health: number;
    attack: number;
    defense: number;
    speed: number;
  };
  // Card lore (Eddie, 2026-11-13): shown on the card's Lore tab,
  // next to the Stats tab that carries the stat block above. Sourced
  // from NAVITAR_LORE (utils/navitarArt.ts) by the records that pass
  // stats; a card without lore keeps the plain stat block, no tabs.
  lore?: string;
  // Art image served from public/navitars/. When absent the card keeps the
  // type-coloured gradient as the visual (the 5 original navitars have no
  // art yet — nothing is invented for them).
  imageUrl?: string;
  // Locked treatment (Eddie's roster-scaling decision, 2026-11-13):
  // a designed navitar that is NOT in the playable stage roster is
  // visible but untouchable. The card renders darkened/silhouetted
  // with a 🔒 LOCKED chip and the unlock-path line (unlockLabel,
  // from utils/lockedRoster.ts). Stats/Lore stay viewable where they
  // exist — visible is the point — and the battle selection logic
  // refuses it (NavitarBattle / NavitarFightClub enforce via
  // isLockedNavitar). A locked PRIME card may carry a view-only
  // modelUrl for the 2D/3D toggle below; Batch/Mystic/Deity locked
  // cards carry none.
  locked?: boolean;
  unlockLabel?: string;
  // Collection-design data (owner-mode full collection): the design's
  // tier and signature ability name from the collection file. Shown
  // in place of stat bars on cards that carry NO stats — stats are
  // never fabricated for a design; a missing tier/ability renders
  // as an honest "—".
  tier?: string;
  abilityName?: string;
  // The design has no portrait yet: the element placeholder on this
  // card is a data gap, not a lock — labelled PLACEHOLDER ART so it
  // is never mistaken for locked styling.
  placeholderArt?: boolean;
  // GLB served from public/models/. When present the card gets the
  // 2D / 3D toggle over the art slot (restored 2026-11-13 on Eddie's
  // call — "bring back the 3-D model toggle" — reversing the
  // 2026-11-12 battles-only removal; the original implementation
  // shipped 2026-11-11 and is restored faithfully). The 3D view is
  // VIEW-ONLY and lazy: ModelViewer mounts only when the toggle is
  // flipped, so no model is fetched on page load, and the view
  // degrades to the 2D art if the renderer cannot mount. On a LOCKED
  // card (the Primes) the toggle changes nothing about selection —
  // the lock stays on in both views; looking is not playing.
  modelUrl?: string;
  // Closer framing for the 3D model (1 = default; the phoenix's wide
  // wingspan needs 1.5 to read at a good size in the card).
  modelZoom?: number;
}

const NavitarCard = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(2),
  borderRadius: theme.shape.borderRadius * 2,
  background: `linear-gradient(135deg, ${theme.palette.background.paper} 0%, ${theme.palette.background.default} 100%)`,
  boxShadow: theme.shadows[4],
  position: 'relative',
  overflow: 'hidden',
  '&::before': {
    content: '""',
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    height: '4px',
    background: 'linear-gradient(90deg, transparent, rgba(255,255,255,0.5), transparent)',
  },
}));

const StatBar = styled(Box)(({ theme }) => ({
  height: '8px',
  borderRadius: '4px',
  background: theme.palette.grey[200],
  position: 'relative',
  overflow: 'hidden',
  '&::after': {
    content: '""',
    position: 'absolute',
    top: 0,
    left: 0,
    height: '100%',
    background: theme.palette.primary.main,
    borderRadius: '4px',
  },
}));

const getTypeColor = (type: string) => {
  switch (type) {
    case 'ice':
      return '#81D4FA';
    case 'fire':
      return '#FF5722';
    case 'nature':
      return '#4CAF50';
    case 'shadow':
      return '#9C27B0';
    case 'light':
      return '#FFC107';
    case 'quantum':
      return '#B388FF';
    case 'electric':
      return '#FFEA00';
    case 'spiritual':
      return '#80DEEA';
    case 'water':
      return '#2196F3';
    default:
      return '#2196F3';
  }
};

const getRarityColor = (rarity: string) => {
  switch (rarity) {
    case 'legendary':
      return '#FFD700';
    case 'epic':
      return '#9C27B0';
    case 'rare':
      return '#2196F3';
    default:
      return '#4CAF50';
  }
};

export const NavitarDesign: React.FC<NavitarDesignProps> = ({
  type,
  name,
  level,
  rarity,
  stats,
  lore,
  imageUrl,
  locked,
  unlockLabel,
  tier,
  abilityName,
  placeholderArt,
  modelUrl,
  modelZoom = 1,
}) => {
  // Stats / Lore tabs (Eddie, 2026-11-13): Stats is the card's
  // original stat block, unchanged and shown by default; Lore swaps
  // it for the dossier text. Only rendered when the card carries
  // lore — a lore-less card looks exactly as it did before.
  const [cardTab, setCardTab] = React.useState<'stats' | 'lore'>('stats');
  // 2D / 3D toggle (restored 2026-11-13): 2D by default; the 3D
  // viewer mounts only on flip, so the model loads lazily.
  const [show3d, setShow3d] = React.useState(false);
  return (
    <NavitarCard data-navitar-name={name} data-locked={locked ? 'true' : undefined}>
      {modelUrl && (
        <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 1 }}>
          <ButtonGroup size="small" aria-label={`${name} view toggle`}>
            <Button
              variant={show3d ? 'outlined' : 'contained'}
              aria-label={`Show 2D art of ${name}`}
              aria-pressed={!show3d}
              onClick={() => setShow3d(false)}
            >
              2D
            </Button>
            <Button
              variant={show3d ? 'contained' : 'outlined'}
              aria-label={`Show 3D model of ${name}`}
              aria-pressed={show3d}
              onClick={() => setShow3d(true)}
            >
              3D
            </Button>
          </ButtonGroup>
        </Box>
      )}
      <Box sx={{ position: 'relative', mb: 2 }}>
        {/* Navitar visual — the art image when one exists, otherwise
            the type-coloured gradient with the pulsing glow. */}
        <Box
          sx={{
            width: '100%',
            height: '200px',
            background: locked
              ? `linear-gradient(135deg, ${getTypeColor(type)}26, rgba(0,0,0,0.45))`
              : `linear-gradient(135deg, ${getTypeColor(type)}40, ${getTypeColor(type)}20)`,
            borderRadius: '16px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            position: 'relative',
            overflow: 'hidden',
          }}
        >
          {show3d && modelUrl ? (
            <ModelViewer
              modelUrl={modelUrl}
              zoom={modelZoom}
              fallbackSrc={imageUrl}
              fallbackAlt={`${name} — 3D preview`}
              element={type}
              height="100%"
            />
          ) : imageUrl ? (
            <NavitarArtImg
              src={imageUrl}
              alt={name}
              element={type}
              style={{
                width: '100%',
                height: '100%',
                ...(locked ? { filter: 'grayscale(75%) brightness(0.5)' } : {}),
              }}
            />
          ) : locked ? (
            /* Locked with no portrait: a silhouette — the element
               glyph rendered solid black over the darkened element
               gradient. Mystics are silhouette-first by design law;
               the other locked designs simply have no art yet, and
               nothing is invented for them. */
            <Box
              aria-hidden
              sx={{
                fontSize: '110px',
                lineHeight: 1,
                filter: 'brightness(0)',
                opacity: 0.55,
                userSelect: 'none',
              }}
            >
              {elementEmoji(type)}
            </Box>
          ) : (
            <Box
              sx={{
                position: 'absolute',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                width: '120px',
                height: '120px',
                borderRadius: '50%',
                background: `radial-gradient(circle, ${getTypeColor(type)}20, transparent)`,
                animation: 'pulse 2s infinite',
                '@keyframes pulse': {
                  '0%': { transform: 'translate(-50%, -50%) scale(1)' },
                  '50%': { transform: 'translate(-50%, -50%) scale(1.2)' },
                  '100%': { transform: 'translate(-50%, -50%) scale(1)' },
                },
              }}
            />
          )}

          {/* LOCKED chip — the untouchable marker, over the art. */}
          {locked && (
            <Chip
              label="🔒 LOCKED"
              size="small"
              sx={{
                position: 'absolute',
                bottom: 8,
                left: 8,
                bgcolor: 'rgba(0,0,0,0.78)',
                color: '#FFD700',
                fontWeight: 'bold',
                border: '1px solid rgba(255,215,0,0.55)',
              }}
            />
          )}
        </Box>

        {/* Level Badge — hidden when the navitar has no level yet
            (locked designs carry none; nothing is invented). */}
        {level !== undefined && (
          <Chip
            label={`Lv. ${level}`}
            size="small"
            sx={{
              position: 'absolute',
              top: 8,
              right: 8,
              bgcolor: 'rgba(0,0,0,0.6)',
              color: 'white',
              fontWeight: 'bold',
            }}
          />
        )}

        {/* Rarity Badge — hidden when the navitar has no rarity yet */}
        {rarity && (
          <Chip
            label={rarity.toUpperCase()}
            size="small"
            sx={{
              position: 'absolute',
              top: 8,
              left: 8,
              bgcolor: getRarityColor(rarity),
              color: 'white',
              fontWeight: 'bold',
            }}
          />
        )}

        {/* Placeholder-art label — the design simply has no portrait
            yet (owner collection). NOT a lock: no lock styling, the
            card stays fully usable. */}
        {placeholderArt && !imageUrl && (
          <Chip
            label="PLACEHOLDER ART"
            size="small"
            sx={{
              position: 'absolute',
              bottom: 8,
              right: 8,
              bgcolor: 'rgba(0,0,0,0.55)',
              color: 'rgba(255,255,255,0.85)',
              fontWeight: 'bold',
              letterSpacing: '0.04em',
            }}
          />
        )}
      </Box>

      <Typography variant="h6" gutterBottom>
        {name}
      </Typography>

      <Chip
        label={type.toUpperCase()}
        size="small"
        sx={{
          bgcolor: getTypeColor(type),
          color: 'white',
          mb: 2,
        }}
      />

      {/* Unlock path — how this design joins the playable roster.
          Wording lives with the design's entry in lockedRoster.ts. */}
      {locked && unlockLabel && (
        <Typography variant="body2" sx={{ mb: 2, fontWeight: 'bold', color: 'text.secondary' }}>
          🔒 {unlockLabel}
        </Typography>
      )}

      {lore && (
        <Box
          sx={{ display: 'flex', gap: 1, mb: 2 }}
          role="tablist"
          aria-label={`${name} card sections`}
        >
          <Chip
            label="Stats"
            size="small"
            role="tab"
            aria-selected={cardTab === 'stats'}
            clickable
            onClick={() => setCardTab('stats')}
            sx={{
              bgcolor: cardTab === 'stats' ? getTypeColor(type) : 'transparent',
              color: cardTab === 'stats' ? 'white' : 'text.secondary',
              border: '1px solid',
              borderColor: cardTab === 'stats' ? getTypeColor(type) : 'divider',
              fontWeight: 'bold',
            }}
          />
          <Chip
            label="Lore"
            size="small"
            role="tab"
            aria-selected={cardTab === 'lore'}
            clickable
            onClick={() => setCardTab('lore')}
            sx={{
              bgcolor: cardTab === 'lore' ? getTypeColor(type) : 'transparent',
              color: cardTab === 'lore' ? 'white' : 'text.secondary',
              border: '1px solid',
              borderColor: cardTab === 'lore' ? getTypeColor(type) : 'divider',
              fontWeight: 'bold',
            }}
          />
        </Box>
      )}

      {lore && cardTab === 'lore' ? (
        <Typography variant="body2" sx={{ lineHeight: 1.6 }}>
          {lore}
        </Typography>
      ) : (
        stats && (
          <Grid container spacing={1}>
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography variant="body2" sx={{ width: '60px' }}>
                  HP
                </Typography>
                <StatBar
                  sx={{ flex: 1, '&::after': { width: `${(stats.health / 100) * 100}%` } }}
                />
                <Typography variant="body2">{stats.health}</Typography>
              </Box>
            </Grid>
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography variant="body2" sx={{ width: '60px' }}>
                  ATK
                </Typography>
                <StatBar
                  sx={{ flex: 1, '&::after': { width: `${(stats.attack / 100) * 100}%` } }}
                />
                <Typography variant="body2">{stats.attack}</Typography>
              </Box>
            </Grid>
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography variant="body2" sx={{ width: '60px' }}>
                  DEF
                </Typography>
                <StatBar
                  sx={{ flex: 1, '&::after': { width: `${(stats.defense / 100) * 100}%` } }}
                />
                <Typography variant="body2">{stats.defense}</Typography>
              </Box>
            </Grid>
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography variant="body2" sx={{ width: '60px' }}>
                  SPD
                </Typography>
                <StatBar sx={{ flex: 1, '&::after': { width: `${(stats.speed / 100) * 100}%` } }} />
                <Typography variant="body2">{stats.speed}</Typography>
              </Box>
            </Grid>
          </Grid>
        )
      )}

      {/* Design block — owner-collection cards carry no stats (none
          are fabricated); the Stats view shows the design's tier and
          signature ability from the collection file instead, with an
          honest "—" where the file records none. */}
      {(!lore || cardTab === 'stats') && !stats && (tier || abilityName) && (
        <Grid container spacing={1}>
          <Grid item xs={12}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Typography variant="body2" sx={{ width: '60px' }}>
                TIER
              </Typography>
              <Typography variant="body2">{tier ?? '—'}</Typography>
            </Box>
          </Grid>
          <Grid item xs={12}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Typography variant="body2" sx={{ width: '60px' }}>
                ABILITY
              </Typography>
              <Typography variant="body2">{abilityName ?? '—'}</Typography>
            </Box>
          </Grid>
        </Grid>
      )}
    </NavitarCard>
  );
};
