const LOCKED_BY_NAME: Record<string, LockedNavitarEntry> = Object.fromEntries(
  LOCKED_NAVITARS.map(e => [e.name.toLowerCase(), e])
);

export function getLockedNavitar(name: string | null | undefined): LockedNavitarEntry | null {
  if (!name) return null;
  return LOCKED_BY_NAME[name.trim().toLowerCase()] ?? null;
}

export function isLockedNavitar(name: string | null | undefined): boolean {
  return getLockedNavitar(name) !== null;
}

export const lockedByKind = (kind: LockedNavitarKind): LockedNavitarEntry[] =>
  LOCKED_NAVITARS.filter(e => e.kind === kind);
