import React, { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { Link as RouterLink } from 'react-router-dom';
import { Box, Button, ButtonGroup, CircularProgress, Paper, Typography } from '@mui/material';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { resolveNavitarArt } from '../utils/navitarArt';
import { AVATAR_OUTFITS, loadAvatarOutfit, saveAvatarOutfit } from '../utils/avatarOutfit';
import type {
  GpsTarget,
  StrollEnvironment,
  StrollWalkerKind,
  TouchKeys,
} from '../components/StrollScene';

// The 3D scene lives behind React.lazy so the (large) three.js code
// splits out of the main bundle and only loads when the Stroll page is
// actually shown — same pattern as ModelViewer. The scene itself uses
// plain three.js, not @react-three/fiber (fiber 9 breaks the React 18
// build outright — see ModelCanvas).
const StrollScene = lazy(() => import('../components/StrollScene'));

// A real browser always defines WebGLRenderingContext; jsdom and
// WebGL-less environments do not. Checking for the constructor (instead
// of calling canvas.getContext) avoids a jsdom "not implemented" console
// error and skips the scene entirely where it cannot run.
function webglAvailable(): boolean {
  if (typeof window === 'undefined') return false;
  const w = window as unknown as { WebGLRenderingContext?: unknown };
  return typeof w.WebGLRenderingContext !== 'undefined';
}

const Stroll: React.FC = () => {
  const { userNavitar } = useNavitarFightClub();
  // One-shot gate: no WebGL, no scene attempt at all — the page stays a
  // friendly message instead of a blank canvas or a crash.
  const [canRender3d] = useState(() => webglAvailable());
  const [environment, setEnvironment] = useState<StrollEnvironment>('forest');
  // The avatar's outfit: a swappable character look, persisted by id.
  // The scene applies it live; the picker just switches the id.
  const [outfit, setOutfit] = useState(() => loadAvatarOutfit());
  const touchKeys = useRef<TouchKeys>({ forward: false, left: false, right: false, back: false });

  const companion = userNavitar
    ? {
        name: userNavitar.name,
        element: userNavitar.element,
        modelUrl: userNavitar.modelUrl,
        modelZoom: userNavitar.modelZoom,
        imageUrl: resolveNavitarArt(userNavitar.imageUrl, userNavitar.name),
      }
    : null;

  // Walk as (Eddie, 2026-11-13): the walker is your navitar by
  // default — its model, or its portrait on a billboard when it has
  // no model. The dress-up avatar (and its outfit picker) stays one
  // tap away. With no navitar yet, the avatar walks alone.
  const [walkAs, setWalkAs] = useState<StrollWalkerKind>(() => {
    try {
      return localStorage.getItem('icewall-stroll-walk-as') === 'avatar' ? 'avatar' : 'navitar';
    } catch {
      return 'navitar';
    }
  });
  const walkerKind: StrollWalkerKind = userNavitar ? walkAs : 'avatar';

  // "Walk with me" — Pokémon-Go mode. The watch lives here on the
  // page; the scene only reads the latest target. Scale: 1 real
  // metre = 3 scene units, so a real walking pace (~1.4 m/s) moves
  // the navitar at ~4.2 units/s — the same pleasant pace as the
  // manual WALK_SPEED. Fixes closer than 1.5 m to the last accepted
  // one are ignored as GPS jitter. INTEGRITY: this is cosmetic
  // only — it never touches the checked-in venue, presence, or any
  // networking state.
  const GPS_SCALE = 3;
  const [gpsOn, setGpsOn] = useState(false);
  const [gpsNote, setGpsNote] = useState<string | null>(null);
  const gpsTarget = useRef<GpsTarget | null>(null);
  const gpsOrigin = useRef<{ lat: number; lon: number } | null>(null);
  const gpsLast = useRef<{ lat: number; lon: number } | null>(null);
  useEffect(() => {
    if (!gpsOn) {
      gpsTarget.current = null;
      gpsOrigin.current = null;
      gpsLast.current = null;
      setGpsNote(null);
      return;
    }
    if (!('geolocation' in navigator)) {
      setGpsNote('Location is off — guide him with the buttons or WASD');
      return;
    }
    const watchId = navigator.geolocation.watchPosition(
      pos => {
        const { latitude, longitude } = pos.coords;
        if (!gpsOrigin.current) {
          gpsOrigin.current = { lat: latitude, lon: longitude };
          gpsLast.current = { lat: latitude, lon: longitude };
          return;
        }
        const last = gpsLast.current ?? gpsOrigin.current;
        const dLat = (latitude - last.lat) * 110540;
        const dLon = (longitude - last.lon) * 111320 * Math.cos((last.lat * Math.PI) / 180);
        if (Math.hypot(dLat, dLon) < 1.5) return; // jitter — ignore
        gpsLast.current = { lat: latitude, lon: longitude };
        const origin = gpsOrigin.current;
        const east = (longitude - origin.lon) * 111320 * Math.cos((origin.lat * Math.PI) / 180);
        const north = (latitude - origin.lat) * 110540;
        const x = Math.max(-82, Math.min(82, east * GPS_SCALE));
        const z = Math.max(-82, Math.min(82, -north * GPS_SCALE));
        gpsTarget.current = { x, z, heading: Math.atan2(x, z) };
        setGpsNote(null);
      },
      () => {
        setGpsNote('Location is off — guide him with the buttons or WASD');
      },
      { enableHighAccuracy: true, maximumAge: 1000 }
    );
    return () => navigator.geolocation.clearWatch(watchId);
  }, [gpsOn]);

  // Hold-to-walk buttons for touch: pressing one sets the same flag the
  // keyboard sets, releasing clears it. touch-action none so the page
  // doesn't scroll while a button is held.
  const holdProps = (key: keyof TouchKeys) => ({
    onPointerDown: (e: React.PointerEvent<HTMLButtonElement>) => {
      e.preventDefault();
      touchKeys.current[key] = true;
    },
    onPointerUp: () => {
      touchKeys.current[key] = false;
    },
    onPointerLeave: () => {
      touchKeys.current[key] = false;
    },
    onPointerCancel: () => {
      touchKeys.current[key] = false;
    },
    onContextMenu: (e: React.MouseEvent<HTMLButtonElement>) => e.preventDefault(),
  });

  return (
    <Box sx={{ p: 2, maxWidth: 1000, margin: '0 auto' }}>
      <Paper sx={{ p: 2, mb: 2 }}>
        <Typography variant="h4" gutterBottom>
          Stroll
        </Typography>
        <Typography variant="body1" color="text.secondary" paragraph>
          Take a walk with your navitar — through the woods, or down the city streets.
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, alignItems: 'center' }}>
          <ButtonGroup aria-label="Stroll environment">
            <Button
              variant={environment === 'forest' ? 'contained' : 'outlined'}
              aria-pressed={environment === 'forest'}
              onClick={() => setEnvironment('forest')}
            >
              🌲 Forest
            </Button>
            <Button
              variant={environment === 'city' ? 'contained' : 'outlined'}
              aria-pressed={environment === 'city'}
              onClick={() => setEnvironment('city')}
            >
              🌆 City
            </Button>
          </ButtonGroup>
          <Typography variant="body1">
            {companion ? `Strolling with ${companion.name}` : 'Strolling solo — no navitar yet'}
          </Typography>
          <Button component={RouterLink} to="/realm" variant="outlined" sx={{ ml: 'auto' }}>
            Back to map
          </Button>
        </Box>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, alignItems: 'center', mt: 2 }}>
          <ButtonGroup aria-label="Walk as">
            <Button
              variant={walkerKind === 'navitar' ? 'contained' : 'outlined'}
              aria-pressed={walkerKind === 'navitar'}
              disabled={!userNavitar}
              onClick={() => {
                setWalkAs('navitar');
                try {
                  localStorage.setItem('icewall-stroll-walk-as', 'navitar');
                } catch {
                  // preference just won't persist
                }
              }}
            >
              Walk as: My Navitar
            </Button>
            <Button
              variant={walkerKind === 'avatar' ? 'contained' : 'outlined'}
              aria-pressed={walkerKind === 'avatar'}
              onClick={() => {
                setWalkAs('avatar');
                try {
                  localStorage.setItem('icewall-stroll-walk-as', 'avatar');
                } catch {
                  // preference just won't persist
                }
              }}
            >
              Avatar
            </Button>
          </ButtonGroup>
          <Button
            variant={gpsOn ? 'contained' : 'outlined'}
            aria-pressed={gpsOn}
            aria-label="Walk with me (GPS)"
            onClick={() => setGpsOn(on => !on)}
          >
            📍 Walk with me
          </Button>
        </Box>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          {walkerKind === 'navitar' && companion
            ? `You are walking as ${companion.name} — guide him anywhere: the world runs three times farther than it used to, and the fog softens the edge.`
            : companion
              ? `${companion.name} walks beside your avatar.`
              : 'Your avatar walks alone until you have a navitar.'}
        </Typography>
        {gpsNote && (
          <Typography variant="body2" sx={{ mt: 1, color: 'warning.main' }} role="note">
            {gpsNote}
          </Typography>
        )}
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          WASD or arrow keys to walk — W forward, A / D to turn, S to step back. On touch, use the
          on-screen buttons. Drag to look around; the camera follows behind you. Trees and buildings
          are scenery for now — you can walk straight through them. With Walk with me on, your
          navitar follows your real footsteps (the buttons and WASD still override); it is a
          cosmetic stroll only — it never changes your check-in or who can see you.
        </Typography>
        {/* Outfit picker: the avatar is a character you dress up, not a
            likeness of anyone. New outfits only need an entry in
            src/utils/avatarOutfit.ts to appear here — shop and earned
            looks plug into this same picker later. */}
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, alignItems: 'center', mt: 2 }}>
          <Typography variant="body2" color="text.secondary">
            Outfit:
          </Typography>
          {AVATAR_OUTFITS.map(o => (
            <Button
              key={o.id}
              size="small"
              variant={outfit.id === o.id ? 'contained' : 'outlined'}
              aria-label={`Wear ${o.name} outfit`}
              aria-pressed={outfit.id === o.id}
              onClick={() => {
                saveAvatarOutfit(o.id);
                setOutfit(o);
              }}
            >
              {o.name} · {o.tag}
            </Button>
          ))}
        </Box>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
          Your avatar is a character you can dress up — outfits are swappable, and more looks (shop
          or earned) can plug in here later.
        </Typography>
      </Paper>

      {!userNavitar && (
        <Paper sx={{ p: 2, mb: 2, border: '1px solid', borderColor: 'primary.main' }}>
          <Typography variant="h6" gutterBottom>
            Create a navitar first
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            You can stroll on your own right now, but your navitar will walk beside you once you
            have one.
          </Typography>
          <Button component={RouterLink} to="/battle" variant="contained">
            Create a navitar
          </Button>
        </Paper>
      )}

      {canRender3d ? (
        <Box
          sx={{
            width: '100%',
            height: 560,
            position: 'relative',
            borderRadius: '16px',
            overflow: 'hidden',
            bgcolor: '#121212',
          }}
        >
          <Suspense
            fallback={
              <Box
                sx={{
                  width: '100%',
                  height: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: 1,
                }}
              >
                <CircularProgress size={20} />
                <Typography variant="body2">Loading the stroll…</Typography>
              </Box>
            }
          >
            <StrollScene
              environment={environment}
              companion={companion}
              outfit={outfit}
              touchKeys={touchKeys}
              walkerKind={walkerKind}
              gpsTarget={gpsTarget}
            />
          </Suspense>
          {/* On-screen walk controls for touch. They sit above the canvas
              so they never fight the drag-to-look gesture. */}
          <Box
            sx={{
              position: 'absolute',
              right: 16,
              bottom: 16,
              display: 'grid',
              gridTemplateColumns: 'repeat(3, 52px)',
              gridTemplateRows: 'repeat(2, 52px)',
              gap: 1,
            }}
          >
            <Box />
            <Button
              variant="contained"
              aria-label="Walk forward"
              sx={{ minWidth: 0, touchAction: 'none', fontSize: '1.2rem' }}
              {...holdProps('forward')}
            >
              ▲
            </Button>
            <Box />
            <Button
              variant="contained"
              aria-label="Turn left"
              sx={{ minWidth: 0, touchAction: 'none', fontSize: '1.2rem' }}
              {...holdProps('left')}
            >
              ◀
            </Button>
            <Button
              variant="contained"
              aria-label="Walk back"
              sx={{ minWidth: 0, touchAction: 'none', fontSize: '1.2rem' }}
              {...holdProps('back')}
            >
              ▼
            </Button>
            <Button
              variant="contained"
              aria-label="Turn right"
              sx={{ minWidth: 0, touchAction: 'none', fontSize: '1.2rem' }}
              {...holdProps('right')}
            >
              ▶
            </Button>
          </Box>
        </Box>
      ) : (
        <Paper sx={{ p: 3 }}>
          <Typography variant="h6" gutterBottom>
            The 3D stroll needs WebGL
          </Typography>
          <Typography variant="body2" color="text.secondary">
            This browser can&apos;t run WebGL, so the stroll can&apos;t load here. Your navitar is
            safe — you can still see it on the map and in your collection.
          </Typography>
        </Paper>
      )}
    </Box>
  );
};

export default Stroll;
